diff --git a/tmp-repro/repro.js b/tmp-repro/repro.js
new file mode 100644
index 0000000..5f716f4
--- /dev/null
+++ b/tmp-repro/repro.js
@@ -0,0 +1,30 @@
+"use strict";
+// Usage: node tmp-repro/repro.js [path-to-eslint-package]  (defaults to this checkout)
+const path = require("node:path");
+const vm = require("node:vm");
+const eslintDir = process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "..");
+const { Linter } = require(path.join(eslintDir, "lib/api.js"));
+const { version } = require(path.join(eslintDir, "package.json"));
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`;
+const config = [{ rules: { "no-var": ["error"] } }];
+const linter = new Linter({ configType: "flat" });
+const messages = linter.verify(code, config);
+const result = linter.verifyAndFix(code, config);
+
+console.log(`== eslint ${version}`);
+for (const m of messages) console.log(`${m.line}:${m.column} ${m.message} (${m.ruleId}) fixable=${Boolean(m.fix)}`);
+console.log(`fixed=${result.fixed}\n${result.output}`);
+
+// Run the (possibly) fixed function body to see whether the fix changed behavior.
+const runnable = result.output.replace(/^export /u, "") + "\na();";
+try {
+    vm.runInNewContext(runnable, { console: { log() {} } });
+    console.log("result: runs fine");
+} catch (e) {
+    console.log(`result: ${e.name}: ${e.message}`);
+}
diff --git a/tmp-repro/run.sh b/tmp-repro/run.sh
new file mode 100755
index 0000000..563c6de
--- /dev/null
+++ b/tmp-repro/run.sh
@@ -0,0 +1,10 @@
+#!/usr/bin/env bash
+# Runs the no-var repro against this checkout and against the reporter's eslint@9.37.0.
+set -e
+here="$(cd "$(dirname "$0")" && pwd)"
+node "$here/repro.js"
+echo
+d="$(mktemp -d)"
+(cd "$d" && echo '{}' > package.json && npm i --silent --no-audit --no-fund eslint@${ESLINT_VERSION:-9.37.0} >/dev/null)
+node "$here/repro.js" "$d/node_modules/eslint"
+rm -rf "$d"
